get_checkout_page.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\CheckoutPage;

$response = CheckoutPage::getCheckoutPage($client);

$settings = $response->map['checkout_page'];
echo 'Billing fields: ', implode(', ', $settings['billing_address']['active_fields']), PHP_EOL;
echo 'Guest checkout: ', $settings['customer_checkout']['checkout_as_guest']['enabled'] ? 'true' : 'false', PHP_EOL;

patch_checkout_page.code:
use WebCommander\Sdk\Resources\Settings\PageSettings\CheckoutPage;

$response = CheckoutPage::patchCheckoutPage($client, [
    'checkout_page' => [
        'order_summary' => ['enable_payment_expand_view' => false],
        'customer_checkout' => ['multiple_shipping_methods' => true],
    ],
]);

$settings = $response->map['checkout_page'];
echo $settings['order_summary']['enable_payment_expand_view'] ? 'true' : 'false', PHP_EOL;
echo $settings['customer_checkout']['multiple_shipping_methods'] ? 'true' : 'false', PHP_EOL;
